import base64, ctypes as c, io, os, shutil, subprocess, time
from pathlib import Path
from pywinauto import Desktop

ROOT=Path(r"C:\dev\flyExplorer")
EXE=ROOT/"out"/"winui"/"Release"/"flyExplorer.exe"
PROFILE=Path(os.environ["USERPROFILE"])
targets=("\ubc14\ud0d5 \ud654\uba74","\ubb38\uc11c","\ub2e4\uc6b4\ub85c\ub4dc","\uc0ac\uc9c4","\uc74c\uc545","\ub3d9\uc601\uc0c1")

def until(fn,why,timeout=30):
    end=time.monotonic()+timeout
    last=None
    while time.monotonic()<end:
        try:
            last=fn()
            if last:return last
        except Exception:pass
        time.sleep(.3)
    raise AssertionError(f"{why}; last={last!r}")

def find_auto(root,auto_id):
    for x in root.descendants():
        try:
            if x.element_info.automation_id==auto_id:return x
        except Exception:pass
    return None

def current_rows(root):
    found={}
    for item in root.descendants():
        try:
            if item.element_info.control_type!="ListItem":continue
            name=item.element_info.name or item.window_text()
            for t in targets:
                if t in name:found.setdefault(t,(item,name))
        except Exception:pass
    return found

def current_artwork(root):
    rows=current_rows(root)
    if len(rows)<6:return None
    for t in targets:
        item,_=rows[t]
        imgs=[x for x in item.descendants() if x.element_info.control_type=="Image"
              and x.element_info.name=="Windows Known Folder artwork"]
        if len(imgs)!=1:return None
    return rows

owned=ROOT/"logs"/"known-folder-after-final"
if owned.exists():shutil.rmtree(owned)
(owned/"localappdata"/"flyExplorer").mkdir(parents=True)
(owned/"localappdata"/"flyExplorer"/"ui-preferences-v1.txt").write_text(
 "schema=2\r\nlanguage=ko-KR\r\ntheme=dark\r\nview=large-icons\r\n",encoding="ascii",newline="")
env=os.environ.copy();env["LOCALAPPDATA"]=str(owned/"localappdata")
p=subprocess.Popen([str(EXE),str(PROFILE)],cwd=EXE.parent,env=env)
w=None
try:
    w=until(lambda:next((x for x in Desktop(backend="uia").windows(process=p.pid)
                        if "flyExplorer" in x.window_text()),None),"window missing")
    try:w.move_window(x=40,y=40,width=972,height=720,repaint=True)
    except Exception:pass
    left=until(lambda:find_auto(w,"LeftFiles"),"LeftFiles missing")
    rows=until(lambda:current_artwork(left),"six Known Folder artworks not settled",30)
    rows=until(lambda:current_artwork(left),"refresh rows",5)
    try:rows["\uc74c\uc545"][0].iface_scroll_item.ScrollIntoView()
    except Exception:pass
    time.sleep(1.5)
    rows=until(lambda:current_artwork(left),"artwork after scroll",10)
    print("AFTER_KNOWN_COUNT",6,"AFTER_GENERIC_COUNT",0,flush=True)
    for t in targets:
        r=rows[t][0].rectangle()
        print("AFTER_ROW",repr(t),r.left,r.top,r.width(),r.height(),flush=True)
    im=w.capture_as_image().convert("RGB")
    buf=io.BytesIO();im.save(buf,format="JPEG",quality=86,optimize=True)
    print("AFTER_SCREENSHOT_BEGIN",flush=True)
    print(base64.b64encode(buf.getvalue()).decode("ascii"),flush=True)
    print("AFTER_SCREENSHOT_END",flush=True)
finally:
    if p.poll() is None:
        if w:c.windll.user32.PostMessageW(w.handle,0x10,0,0)
        try:p.wait(timeout=10)
        except subprocess.TimeoutExpired:p.terminate();p.wait(timeout=8)
print("AFTER_EXIT",p.returncode,flush=True)

